CREATE OR REPLACE FUNCTION public.authorize_my_routing_candidate(p_request uuid, p_candidate uuid, p_depart_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET extra_float_digits TO '0'
AS $function$
