 UPDATE public.pickup_routes SET route_status='ABANDONED' WHERE route_id=p_route;
 UPDATE routing_private.bindings SET closed_at=clock_timestamp() WHERE route_id=p_route;
 INSERT INTO public.audit_events(actor_user_id,actor_role,entity_type,entity_id,event_type,request_id,outcome,details)
 VALUES(ngo,'NGO','ROUTE',p_route,'CLOSE_MIXED_OUTCOME_ROUTE',p_request,'SUCCESS',jsonb_build_object('final_pickup_count',n,'collected_pickup_count',(SELECT count(*) FROM routing_private.items WHERE route_id=p_route AND collected_at IS NOT NULL),'resolved_uncollected_count',(SELECT count(*) FROM routing_private.deferred_stops WHERE route_id=p_route AND status='RESOLVED_UNCOLLECTED'),'vehicle_depot_return_confirmed',true,'closure_kind',result->>'outcome','vehicle_accountability_confirmed',true,'meaning','At least one independently resolved uncollected pickup; every pickup has a valid final outcome.'));
 RETURN result;
END $function$

